static int db_open_contact(int npc){char why[96];int i=dockbay_hail(&game,npc,why,sizeof(why));if(i==-1)return 0;if(i==-2){message(&game,why);return 1;}if(i==-3){i=dockbay_actor(&game,npc);db_return_page=FLIGHT;db_enter(i,4);db_commit();return 1;}DockAd *a=db_ad(i);db_quantity=a->kind==DB_MODULE?1:a->kind==DB_BUY_CARGO?game.cargo[a->item]-mission_cargo_reserved(&game,a->item):dockbay_cargo_free(&game,a->item);if(db_quantity>(int)a->stock)db_quantity=a->stock;if(db_quantity<0)db_quantity=0;db_revision=a->revision;db_return_page=FLIGHT;db_enter(i,1);return 1;}
