static const char *db_signoff(const DockAd *a){static const char *say[]={"Lovely. Now I can afford the next terrible idea. Safe flying!","That's one less box for the move. Thank you, Commander!","It is yours now. Please give it a happier home than I did.","A fine piece, and a fine ship to put it in. Enjoy it!","My first customer! Well, this has made my entire week.","A pleasure. I'll keep your remaining food right here.","Less rattling in my hold, more useful cargo in yours!","Good part, that. The figures are exactly what we agreed.","The crew can stop eating emergency biscuits. Thank you!","Give it a proper run. You've bought yourself a good upgrade."};return game.dockbay.seller[a->seller].trusted?"Always a pleasure, Commander. I'll put fresh stock on DockBay after I leave.":say[a->encounter%10];}
