  if(pressed&PSP_CTRL_SQUARE){if(db_detail>=0&&db_detail<DB_ADS){db_ad(db_detail)->flags^=DB_WATCH;game.dockbay.dirty=1;db_commit();}else if(db_detail<0){db_filter=(db_filter+1)%5;db_cursor=0;}game.cue=SFX_SELECT;return 1;}
